-- specs/046-subgroup-requirement-checklist.
--
-- What each document sub-group is supposed to hold, and whether it does.
--
-- หมวด 6 became a submission checklist: the officer asks for specific documents
-- and each sub-group exists to hold a particular set of them. The folder name
-- cannot say which ones, an empty folder says nothing at all, and a full one can
-- still be wrong (the SUZUYO test reports). Until now that knowledge lived in a
-- Google Doc regenerated by hand.
--
-- Applied by hand in the Supabase SQL Editor — there is no DDL path from the
-- app's machine. The app tolerates this migration being absent (research
-- Decision 4), so deploying the code first is safe. Idempotent: safe to re-run.

-- ---------------------------------------------------------------------------
-- Schema
-- ---------------------------------------------------------------------------

alter table document_categories add column if not exists description text;
alter table document_groups add column if not exists description text;

create table if not exists document_group_requirements (
  id uuid primary key default gen_random_uuid(),
  -- Items describe what a folder should hold; they are not documents, so they
  -- go with their sub-group rather than blocking its deletion (FR-015).
  group_id uuid not null references document_groups (id) on delete cascade,
  name_th text not null check (btrim(name_th) <> ''),
  status text not null default 'missing' check (status in ('have', 'missing', 'waiting')),
  note text,
  sort_order integer not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists document_group_requirements_group_idx
  on document_group_requirements (group_id, sort_order);

alter table document_group_requirements enable row level security;

-- Same shape as every other table: the real authorization is the
-- requireRole("editor") check in the Server Actions, not RLS.
drop policy if exists "authenticated full access document_group_requirements" on document_group_requirements;
create policy "authenticated full access document_group_requirements" on document_group_requirements
  for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

-- ---------------------------------------------------------------------------
-- Initial content for หมวด 6 — the spec appendix, checked against every file's
-- contents on 2026-09-17. lib/requirement-seed.test.ts requires these rows to
-- match the appendix exactly (SC-002).
--
-- Safe to run again (FR-018):
--   * a description is only written where it is still empty, so editing it in
--     the app afterwards is never overwritten;
--   * a sub-group's items are only inserted when it has none, so nothing is
--     duplicated and nothing an editor changed is reset;
--   * sub-groups are matched by exact name inside checklist-permit — one renamed
--     or removed since the audit matches nothing and is skipped, rather than its
--     items landing somewhere they do not belong.
-- ---------------------------------------------------------------------------

with category_wording (description) as (values ('ชุดเอกสารสำหรับยื่นขออนุญาตระบบความปลอดภัยอาคารต่อเจ้าพนักงานท้องถิ่น จัดเรียงตาม checklist ที่เจ้าหน้าที่ขอ ไฟล์ในหมวดนี้เป็นสำเนาที่คัดมาจากหมวด 1-5 ต้นฉบับยังอยู่ในหมวดเดิมเสมอ'))
update document_categories c
set description = category_wording.description
from category_wording
where c.slug = 'checklist-permit'
  and c.description is null;

