insert into document_group_requirements (group_id, name_th, status, note, sort_order)
select g.id, seed_items.name_th, seed_items.status, seed_items.note, seed_items.position
from seed_items
join document_groups g on g.name_th = seed_items.group_name
join document_categories c on c.id = g.category_id and c.slug = 'checklist-permit'
where not exists (select 1 from document_group_requirements r where r.group_id = g.id)
order by g.id, seed_items.position;
